let file = """{"version":3,"file":"auth-yVMbJVyD.js","names":[],"sources":["../../src/platform/cloud/onboarding/auth.ts"],"sourcesContent":["import { addBreadcrumb } from '@sentry/vue'\nimport { watch } from 'vue'\n\nimport { firebaseIdentity } from '@/platform/auth/firebaseIdentity'\n\nimport {\n  consumeSurveyReplayRequest,\n  isSurveyReplayRequested\n} from '@/platform/onboarding/onboardingReplay'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { api } from '@/scripts/api'\nimport { useAuthStore } from '@/stores/authStore'\nimport { toError } from '@/utils/errorUtil'\n\ninterface UserCloudStatus {\n  status: 'active'\n}\n\nconst ONBOARDING_SURVEY_KEY = 'onboarding_survey'\n\nfunction captureApiError(\n  error: Error,\n  endpoint: string,\n  errorType: 'http_error' | 'network_error',\n  httpStatus?: number,\n  operation?: string,\n  extraContext?: Record<string, unknown>\n) {\n  reportError(error, {\n    surface: 'platform',\n    errorType,\n    tags: {\n      api_endpoint: endpoint,\n      http_status: httpStatus,\n      operation\n    },\n    context: extraContext\n  })\n}\n\nfunction isHttpError(error: unknown, errorMessagePrefix: string): boolean {\n  return error instanceof Error && error.message.startsWith(errorMessagePrefix)\n}\n\nexport async function getUserCloudStatus(): Promise<UserCloudStatus> {\n  try {\n    const response = await api.fetchApi('/user', {\n      method: 'GET',\n      headers: {\n        'Content-Type': 'application/json'\n      }\n    })\n    if (!response.ok) {\n      const error = new Error(`Failed to get user: ${response.statusText}`)\n      captureApiError(\n        error,\n        '/user',\n        'http_error',\n        response.status,\n        undefined,\n        {\n          api: {\n            method: 'GET',\n            endpoint: '/user',\n            status_code: response.status,\n            status_text: response.statusText\n          }\n        }\n      )\n      throw error\n    }\n\n    return response.json()\n  } catch (error) {\n    if (!isHttpError(error, 'Failed to get user:')) {\n      captureApiError(toError(error), '/user', 'network_error')\n    }\n    throw error\n  }\n}\n\nexport async function getSurveyCompletedStatus(\n  ownerId: string | undefined\n): Promise<boolean> {\n  if (isSurveyReplayRequested(ownerId)) return false\n\n  return (await readStoredSurvey()) !== 'absent'\n}\n\ntype StoredSurvey = 'present' | 'absent' | 'unknown'\n\nfunction classifyStoredSurvey(data: unknown): StoredSurvey {\n  if (typeof data !== 'object' || data === null || !('value' in data)) {\n    return 'unknown'\n  }\n  const value = data.value\n  if (value === null) return 'absent'\n  if (typeof value !== 'object' || Array.isArray(value)) return 'unknown'\n  return Object.keys(value).length === 0 ? 'absent' : 'present'\n}\n\nasync function readStoredSurvey(signal?: AbortSignal): Promise<StoredSurvey> {\n  try {\n    const response = await api.fetchApi(`/settings/${ONBOARDING_SURVEY_KEY}`, {\n      method: 'GET',\n      signal,\n      headers: {\n        'Content-Type': 'application/json'\n      }\n    })\n    if (response.status === 404) {\n      return 'absent'\n    }\n    if (!response.ok) {\n      addBreadcrumb({\n        category: 'auth',\n        message: 'Survey status check returned non-ok response',\n        level: 'warning',\n        data: {\n          status: response.status,\n          endpoint: `/settings/${ONBOARDING_SURVEY_KEY}`\n        }\n      })\n      return 'unknown'\n    }\n    const data: unknown = await response.json()\n    return classifyStoredSurvey(data)\n  } catch (error) {\n    if (signal?.aborted && error === signal.reason) return 'unknown'\n    reportError(error, {\n      surface: 'platform',\n      errorType: 'network_error',\n      tags: { api_endpoint: '/settings/{key}' },\n      context: {\n        route_template: '/settings/{key}',\n        route_actual: `/settings/${ONBOARDING_SURVEY_KEY}`\n      },\n      level: 'warning'\n    })\n    return 'unknown'\n  }\n}\n\nexport type SurveySubmissionResult =\n  | { status: 'stored' }\n  | { status: 'preserved' }\n  | { status: 'failed'; cause: unknown }\n  | { status: 'cancelled' }\n\nexport async function submitSurvey(\n  survey: Record<string, unknown>,\n  ownerId: string\n): Promise<SurveySubmissionResult> {\n  const identityChanged = new AbortController()\n  const auth = useAuthStore()\n  const abortUnlessOwner = (firebaseUid: string | undefined) => {\n    if ((firebaseUid ?? auth.sessionOnlyUser?.id) !== ownerId) {\n      identityChanged.abort()\n    }\n  }\n  const stopWatchingFirebase = firebaseIdentity.onUserChanged((user) =>\n    abortUnlessOwner(user?.uid)\n  )\n  const stopWatchingSession = watch(\n    () => auth.sessionOnlyUser?.id,\n    () => abortUnlessOwner(auth.currentUser?.uid),\n    { flush: 'sync' }\n  )\n\n  try {\n    const replaying = isSurveyReplayRequested(ownerId)\n    if (replaying) {\n      const stored = await readStoredSurvey(identityChanged.signal)\n      if (identityChanged.signal.aborted) return { status: 'cancelled' }\n      if (stored === 'unknown') {\n        return {\n          status: 'failed',\n          cause:\n            'Could not read the stored survey answers, so the replayed submission was not written'\n        }\n      }\n      if (stored === 'present') {\n        consumeSurveyReplayRequest(ownerId)\n        return { status: 'preserved' }\n      }\n    }\n\n    addBreadcrumb({\n      category: 'auth',\n      message: 'Submitting survey',\n      level: 'info',\n      data: {\n        survey_fields: Object.keys(survey)\n      }\n    })\n\n    const response = await api.fetchApi('/settings', {\n      method: 'POST',\n      signal: identityChanged.signal,\n      headers: {\n        'Content-Type': 'application/json'\n      },\n      body: JSON.stringify({ [ONBOARDING_SURVEY_KEY]: survey })\n    })\n\n    if (identityChanged.signal.aborted) return { status: 'cancelled' }\n    if (!response.ok) {\n      const error = new Error(`Failed to submit survey: ${response.statusText}`)\n      captureApiError(\n        error,\n        '/settings',\n        'http_error',\n        response.status,\n        'submit_survey',\n        {\n          survey: {\n            field_count: Object.keys(survey).length,\n            field_names: Object.keys(survey)\n          }\n        }\n      )\n      return { status: 'failed', cause: error }\n    }\n\n    if (replaying) consumeSurveyReplayRequest(ownerId)\n\n    addBreadcrumb({\n      category: 'auth',\n      message: 'Survey submitted successfully',\n      level: 'info'\n    })\n\n    return { status: 'stored' }\n  } catch (error) {\n    if (\n      identityChanged.signal.aborted &&\n      error === identityChanged.signal.reason\n    )\n      return { status: 'cancelled' }\n    captureApiError(\n      toError(error),\n      '/settings',\n      'network_error',\n      undefined,\n      'submit_survey'\n    )\n    return { status: 'failed', cause: error }\n  } finally {\n    stopWatchingFirebase()\n    stopWatchingSession()\n  }\n}\n"],"mappings":"iVAkBA,IAAM,EAAwB,oBAE9B,SAAS,gBACP,EACA,EACA,EACA,EACA,EACA,EACA,CACA,EAAY,EAAO,CACjB,QAAS,WACT,YACA,KAAM,CACJ,aAAc,EACd,YAAa,EACb,WACF,EACA,QAAS,CACX,CAAC,CACH,CAEA,SAAS,YAAY,EAAgB,EAAqC,CACxE,OAAO,aAAiB,OAAS,EAAM,QAAQ,WAAW,CAAkB,CAC9E,CAEA,eAAsB,oBAA+C,CACnE,GAAI,CACF,IAAM,EAAW,MAAM,EAAI,SAAS,QAAS,CAC3C,OAAQ,MACR,QAAS,CACP,eAAgB,kBAClB,CACF,CAAC,EACD,GAAI,CAAC,EAAS,GAAI,CAChB,IAAM,EAAY,MAAM,uBAAuB,EAAS,YAAY,EAgBpE,MAfA,gBACE,EACA,QACA,aACA,EAAS,OACT,IAAA,GACA,CACE,IAAK,CACH,OAAQ,MACR,SAAU,QACV,YAAa,EAAS,OACtB,YAAa,EAAS,UACxB,CACF,CACF,EACM,CACR,CAEA,OAAO,EAAS,KAAK,CACvB,OAAS,EAAO,CAId,MAHK,YAAY,EAAO,qBAAqB,GAC3C,gBAAgB,EAAQ,CAAK,EAAG,QAAS,eAAe,EAEpD,CACR,CACF,CAEA,eAAsB,yBACpB,EACkB,CAGlB,MAFA,CAAI,EAAwB,CAAO,GAE3B,MAAM,iBAAiB,IAAO,QACxC,CAIA,SAAS,qBAAqB,EAA6B,CACzD,GAAI,OAAO,GAAS,WAAY,GAAiB,EAAE,UAAW,GAC5D,MAAO,UAET,IAAM,EAAQ,EAAK,MAGnB,OAFI,IAAU,KAAa,SACvB,OAAO,GAAU,UAAY,MAAM,QAAQ,CAAK,EAAU,UACvD,O